import AVFoundation
import InnerTubeKit
import SwiftUI

/// A captions pick (nil = Off): a language, and whether it is YouTube's auto-generated track
/// (InnerTubeKit timedtext, drawn by `CaptionOverlay`) or the uploader's (an HLS SUBTITLES
/// rendition in the item's legible group, drawn by AVFoundation). Session-only, never persisted.
struct CaptionChoice: Equatable {
    var languageCode: String
    var isAutoGenerated: Bool
    /// Which of the video's tracks of this kind in this language (0 = the first): an uploader can
    /// publish two in one language, and each is its own pick.
    var ordinal = 0

    /// The pick read against one video's tracks -- Up Next carries the LANGUAGE over (Android
    /// `setPreferredTextLanguage`, `PlayerFragment.kt:549-553`): the same kind in that language
    /// (that track if this video has as many, else the first), else the other kind, else Off for
    /// this video. The pick itself stays for the next one.
    static func resolve(_ choice: CaptionChoice?, uploader: [String], auto: [String]) -> CaptionChoice? {
        guard let choice else { return nil }
        let (same, other) = choice.isAutoGenerated ? (auto, uploader) : (uploader, auto)
        if same.contains(choice.languageCode) {
            return same.filter { $0 == choice.languageCode }.count > choice.ordinal
                ? choice : CaptionChoice(languageCode: choice.languageCode, isAutoGenerated: choice.isAutoGenerated)
        }
        if other.contains(choice.languageCode) {
            return CaptionChoice(languageCode: choice.languageCode, isAutoGenerated: !choice.isAutoGenerated)
        }
        return nil
    }
}

/// The captions menu (spec §10 Captions paragraph; Android `SubtitlePickerDialog.kt:40-53`) --
/// FitrahTube's own SwiftUI control, same reasoning as `PlayerScreen.qualityMenu`/`AudioLanguageMenu`,
/// and the ONE place a caption is picked: Off, then the uploader's tracks (the live item's legible
/// group), then YouTube's auto-generated ones (`PlayerScreen.captionTracks`). One source at a time.
/// Hidden when the video has neither kind (`PlayerFragment.kt:1531-1532`), and while audio-only, where
/// nothing is drawn (`overlayTrack`) -- here, so every screen that mounts it agrees. Starts Off on every
/// open and never picks by itself. AVKit's own ⋯ > Subtitles lists the uploader tracks too;
/// `load` keeps this menu in step with it.
///
/// B4 Task 3: ONE copy, shared by `ShortsScreen`'s rail and the main player. Identifiers stay
/// `player.*` -- B1's tests assert on them.
struct CaptionsMenu: View {
    let model: PlayerViewModel

    var body: some View {
        let entries = Self.entries(model)
        if entries.count > 1, !model.audioOnly {
            let active = Self.effective(model)
            Menu {
                Section(String(localized: "player_captions_dialog_title")) {
                    ForEach(Array(entries.enumerated()), id: \.offset) { _, entry in
                        Button {
                            Self.pick(entry.choice, model)
                        } label: {
                            if entry.choice == active {
                                Label(entry.label, systemImage: "checkmark")
                            } else {
                                Text(entry.label)
                            }
                        }
                        .accessibilityIdentifier(Self.identifier(entry.choice))
                    }
                }
            } label: {
                Image(systemName: "captions.bubble").shortsGlyph()
            }
            .accessibilityIdentifier("player.captionsMenu.button")
            .accessibilityLabel(String(localized: "player_action_captions"))
            // Task 10: "Captions, Off" (spec §6.11 example, verbatim) when nothing is on, else the
            // active entry's own label.
            .accessibilityValue(entries.first { $0.choice == active }?.label ?? String(localized: "player_captions_off"))
        }
    }

    struct Entry: Equatable {
        let choice: CaptionChoice?
        let label: String
    }

    /// Off, uploader, auto-generated -- Android's order. Pure, so a test pins it. Each uploader track
    /// is its own entry, numbered within its language; a name two of them share gets a number too.
    static func entries(uploader: [(languageCode: String, name: String)], auto: [CaptionTrack]) -> [Entry] {
        [Entry(choice: nil, label: String(localized: "player_captions_off"))]
            + uploader.indices.map { i in
                let track = uploader[i], before = uploader[..<i]
                let namesakes = uploader.filter { $0.name == track.name }.count
                let number = (before.filter { $0.name == track.name }.count + 1).formatted(.number.locale(Format.numberLocale(.current)))
                return Entry(choice: CaptionChoice(languageCode: track.languageCode, isAutoGenerated: false,
                                                   ordinal: before.filter { $0.languageCode == track.languageCode }.count),
                             label: namesakes > 1 ? "\(track.name) \(number)" : track.name)
            }
            + auto.map { Entry(choice: CaptionChoice(languageCode: $0.languageCode, isAutoGenerated: true), label: captionLabel($0)) }
    }

    static func entries(_ model: PlayerViewModel) -> [Entry] {
        entries(uploader: uploaderOptions(model).map { (languageCode(of: $0), $0.displayName) },
                auto: PlayerScreen.captionTracks(model.state))
    }

    /// The language named from its code, plus -- from the structured `kind=asr` flag, once -- the
    /// app's "(Auto-generated)" marker. YouTube's own `languageName` already ends "(auto-generated)"
    /// for these, which is why it is only the fallback, unmarked.
    static func captionLabel(_ track: CaptionTrack) -> String {
        guard let name = Locale.current.localizedString(forIdentifier: track.languageCode) else { return track.languageName }
        return track.isAutoGenerated ? String(format: String(localized: "player_captions_auto_generated"), name) : name
    }

    /// `player.captionsOption.off`, `.<code>` (auto-generated -- B1's tests) or `.uploader.<code>`,
    /// plus `.2`, `.3` … for a language's second and later tracks.
    static func identifier(_ choice: CaptionChoice?) -> String {
        guard let choice else { return "player.captionsOption.off" }
        return "player.captionsOption." + (choice.isAutoGenerated ? "" : "uploader.") + choice.languageCode
            + (choice.ordinal > 0 ? ".\(choice.ordinal + 1)" : "")
    }

    /// The live item's uploader tracks: its legible group minus the "Forced" twins AVFoundation
    /// synthesises for some sources (forced-only subtitles are not something to pick).
    static func uploaderOptions(_ model: PlayerViewModel) -> [AVMediaSelectionOption] {
        guard let group = model.legibleGroup else { return [] }
        return AVMediaSelectionGroup.mediaSelectionOptions(from: group.options,
                                                           withoutMediaCharacteristics: [.containsOnlyForcedSubtitles])
    }

    static func languageCode(of option: AVMediaSelectionOption) -> String {
        option.extendedLanguageTag ?? option.locale?.identifier ?? option.displayName
    }

    /// The pick as it applies to the CURRENT video (`CaptionChoice.resolve`) -- what the checkmark,
    /// the item's legible selection and the overlay all follow.
    /// ponytail: until a new item's legible group has loaded, an uploader pick can resolve to the
    /// same language's auto-generated track for that moment. Gate on the load if that ever shows.
    static func effective(_ model: PlayerViewModel) -> CaptionChoice? {
        CaptionChoice.resolve(model.captionChoice,
                              uploader: uploaderOptions(model).map(languageCode(of:)),
                              auto: PlayerScreen.captionTracks(model.state).map(\.languageCode))
    }

    /// The auto-generated track `CaptionOverlay` draws, when the effective pick is one. Never in
    /// audio-only, where this menu hides itself too (Android's audio-only source has no text track
    /// either); the pick stays for when the video comes back.
    static func overlayTrack(_ model: PlayerViewModel) -> CaptionTrack? {
        guard !model.audioOnly, let effective = effective(model), effective.isAutoGenerated else { return nil }
        return PlayerScreen.captionTracks(model.state).first { $0.languageCode == effective.languageCode }
    }

    /// A pick in this menu. Off clears both sources; an uploader track is selected into the item's
    /// legible group (AVFoundation draws it, AirPlay carries it, AVKit's menu shows it); an
    /// auto-generated one empties that group so only the overlay draws.
    static func pick(_ choice: CaptionChoice?, _ model: PlayerViewModel) {
        model.captionChoice = choice
        applyToItem(model)
    }

    private static func applyToItem(_ model: PlayerViewModel) {
        guard let item = model.currentItem, let group = model.legibleGroup else { return }
        let effective = effective(model)
        let option = effective.flatMap { pick in
            pick.isAutoGenerated ? nil
                : uploaderOptions(model).filter { languageCode(of: $0) == pick.languageCode }.dropFirst(pick.ordinal).first
        }
        item.select(option, in: group)
    }

    /// Run by `PlayerViewModel.currentItem`'s `didSet` on every new item, beside the audio load:
    /// lists the item's uploader tracks, applies the pick (Off on a fresh screen -- AVFoundation may
    /// have selected a track by itself), and from then on follows AVKit's own Subtitles menu.
    static func load(_ model: PlayerViewModel) async {
        let item = model.currentItem
        let group = try? await item?.asset.loadMediaSelectionGroup(for: .legible)
        guard let item, item === model.currentItem, let group else { return }
        model.legibleGroup = group
        applyToItem(model)
        model.captionSelectionSync = NotificationCenter.default
            .publisher(for: AVPlayerItem.mediaSelectionDidChangeNotification, object: item)
            .receive(on: DispatchQueue.main)
            .sink { [weak model] _ in
                MainActor.assumeIsolated {
                    guard let model, item === model.currentItem else { return }
                    followItemSelection(model)
                }
            }
    }

    /// AVKit's ⋯ > Subtitles selects straight into the item. A language picked there becomes the
    /// pick (replacing an auto-generated one); Off there clears an uploader pick. Our own selections
    /// land here too and change nothing, since they already match `effective`.
    /// ponytail: Off there while an auto-generated track shows changes nothing (owner-accepted), and
    /// this menu is not on screen in iPad AVKit fullscreen, where the auto-generated cue now shows
    /// (`PlayerHostView.HostedCaptions`): there it is Done, then this menu's Off (owner-accepted,
    /// stage 7 r2 N5). iOS has no public API to add an item to AVKit's own menus
    /// (`transportBarCustomMenuItems` is tvOS-only); an iPad fullscreen of our own with this menu is
    /// on the 1.0.4 list.
    private static func followItemSelection(_ model: PlayerViewModel) {
        guard let item = model.currentItem, let group = model.legibleGroup else { return }
        if let option = item.currentMediaSelection.selectedMediaOption(in: group) {
            let code = languageCode(of: option)
            let picked = CaptionChoice(languageCode: code, isAutoGenerated: false,
                                       ordinal: uploaderOptions(model).filter { languageCode(of: $0) == code }
                                           .firstIndex(of: option) ?? 0)
            if picked != effective(model) { model.captionChoice = picked }
        } else if effective(model)?.isAutoGenerated == false {
            model.captionChoice = nil
        }
    }
}
